def get_keywords(vendor_name: str) -> dict[str, list[str]]:
    """Case-insensitive lookup. Returns empty dict if not found."""
    return VENDOR_KEYWORDS.get(vendor_name) or VENDOR_KEYWORDS.get(vendor_name.lower(), {})


def get_search_terms(vendor_name: str) -> list[str]:
    """Flat list of all keywords for a vendor — for query enrichment."""
    kw = get_keywords(vendor_name)
    terms: list[str] = []
    for lst in kw.values():
        terms.extend(lst)
    return list(dict.fromkeys(terms))  # deduplicated, order preserved
